const fs=require('node:fs'), vm=require('node:vm'), ts=require('typescript'), THREE=require('three');
const fixedMath=Object.create(Math); fixedMath.random=()=>0;
const compile=s=>ts.transpileModule(s,{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2020}}).outputText;
const load=(s,req)=>{const out={};vm.runInNewContext(compile(s),{exports:out,require:req,Math:fixedMath,console,AbortController});return out};
const source=fs.readFileSync('src/core/radio.ts','utf8').replace("import.meta.env.MODE !== 'single'",'false');
const R=load(source,n=>n==='three'?THREE:{RadioVoice:class{resolve(){return null}}});
const T=load(fs.readFileSync('src/story/tripRadio.ts','utf8'),n=>n==='../core/radio'?R:{MOTEL_AT:{z:650}});
const time=load(fs.readFileSync('src/story/time.ts','utf8'),()=>undefined);
const N=load(fs.readFileSync('src/story/nightEvents.ts','utf8'),n=>n==='three'?THREE:time);
const results=[];
for(const speed of [18,12]){
 const radio=new R.Radio({ctx:null}); radio.boyCalled=true; radio.reset(8160);
 const seen=new Set(), tr=new T.TripRadio(radio,seen), pieces=[];
 let last='',start=null,end=null,clock=8160,archiveSegment=null;
 for(let step=0;step<Math.ceil(2323/speed);step++){
  for(let frame=0;frame<20;frame++){
   const t=step+frame/20,metres=t*speed; clock+=.05;
   radio.update(.05,clock);
   tr.update({trip:{n:1,from:'saro',to:'diner',bound:'diner',metres},phase:'ch1',clock,tuned:'caliche'});
   if(start===null&&metres>1250&&radio.stations.caliche.free){
    if(radio.stations.caliche.cutIn(N.BULLETIN,clock)){start={seconds:t,metres};archiveSegment=radio.stations.caliche.seg;}
   }
   if(start&&end===null&&radio.stations.caliche.seg!==archiveSegment)end={seconds:t,metres};
   if(tr.last&&tr.last.id!==last){last=tr.last.id;pieces.push({id:last,seconds:t,metres:Math.round(metres),acceptedAt:Math.round(tr.last.metres)});}
  }
 }
 const after=end?pieces.find(p=>p.seconds>=end.seconds):null;
 results.push({speed,archiveStart:start,archiveEnd:end,idealArrivalSeconds:2323/speed,
   afterArchiveGap:after?after.seconds-end.seconds:null,pieces,kept:[...seen]});
}
return results;
